  // ── Space '1' Country Intelligence dashboard flow ─────────────────────────────

  private handleSpace1Message(text: string): void {
    const t = text.toLowerCase();
    if (t.includes('debt')) {
      this.stepDebtGDPQuery();
    } else if (t.includes('gdp') || t.includes('growth') || t.includes('projection')) {
      this.stepGDPQuery();
    } else if (t.includes('credit') || t.includes('rating')) {
      this.stepCreditQuery();
    } else {
      this.stepGDPQuery();
    }
  }

  private stepDebtGDPQuery(): void {
    this.startThinking(
      ['Analysing Fiscal Data', 'Comparing Countries'],
      [
        { title: 'Query Debt-to-GDP series', description: 'KIDB · Bangladesh · Viet Nam · Cambodia · 2020–2024' },
        { title: 'Rank by fiscal position',  description: 'Computing 2024 values and 5-year trend' },
      ],
      2000,
      () => {
        this.push({
          role: 'assistant',
          text: 'All three economies maintain **relatively low debt-to-GDP ratios** by global standards. Viet Nam has made the sharpest fiscal consolidation — from 55.9% in 2020 down to 36.7% in 2024, driven by strong nominal GDP growth. Bangladesh is stable near 38%, while Cambodia remains the most conservative at 31.4%.',
          suggestedMetrics: CI_METRIC_CARDS,
          sources: 1,
          sourceCards: [
            { type: 'dataset', title: 'Key Indicators Database (KIDB)', description: 'ADB flagship time-series database — fiscal indicators for all DMCs, 1960–2024.', updatedAt: '30 Jun 2026' },
          ],
          actions: ['Compare with South Asia peers', 'Show GDP projections'],
        });
      },
    );
  }

  private stepGDPQuery(): void {
    this.startThinking(
      ['Retrieving GDP Series', 'Projecting Trends'],
      [
        { title: 'Query GDP growth series',  description: 'KIDB · 2020–2024 actuals' },
        { title: 'Extrapolate 2025–2030',    description: 'IMF WEO baseline scenario' },
      ],
      2200,
      () => {
        this.push({
          role: 'assistant',
          text: 'Based on 2020–2024 actuals and IMF WEO projections, all three economies are expected to sustain **above-average growth through 2030**. Viet Nam leads at a projected 6.5–7% annually, supported by manufacturing FDI. Bangladesh is forecast at 6–6.5%, with garments and remittances as the backbone. Cambodia tracks at around 6%.\n\nElevated inflation in Bangladesh (7.8%) remains a growth risk — add both cards to compare the growth-inflation tradeoff.',
          suggestedMetrics: CI_METRIC_CARDS,
          sources: 2,
          sourceCards: [
            { type: 'dataset', title: 'Key Indicators Database (KIDB)', description: 'ADB flagship time-series database — GDP growth and macroeconomic indicators, 1960–2024.', updatedAt: '30 Jun 2026' },
            { type: 'dataset', title: 'IMF World Economic Outlook',     description: 'IMF WEO projections — GDP, inflation, and fiscal indicators for 190 economies.', updatedAt: '01 May 2026' },
          ],
          actions: ['Show credit rating context', 'Add Debt-to-GDP card'],
        });
      },
    );
  }

  private stepCreditQuery(): void {
    this.startThinking(
      ['Retrieving Rating History', 'Analysing Credit Drivers'],
      [
        { title: 'Load sovereign credit ratings', description: 'S&P · Moody\'s · 5-year history' },
        { title: 'Map to macro indicators',        description: 'CPI · Current Account · Debt/GDP' },
      ],
      2000,
      () => {
        this.push({
          role: 'assistant',
          text: 'Credit rating trajectories reflect each country\'s macro fundamentals. **Viet Nam (BB+)** benefits from a current account surplus and a declining debt trajectory. **Bangladesh (BB−)** faces pressure from elevated inflation (7.8%) and a persistent current account deficit. **Cambodia (B+)** remains lower-rated due to its wide external deficit.\n\nThe two indicators most correlated with rating movements are inflation and the current account balance.',
          suggestedMetrics: CI_METRIC_CARDS,
          sources: 2,
          sourceCards: [
            { type: 'dataset', title: 'Country Credit Profiles and Ratings (CSV)', description: 'ADB-maintained sovereign credit rating history and outlook across all DMCs.', updatedAt: '15 Jul 2026' },
            { type: 'dataset', title: 'Key Indicators Database (KIDB)',            description: 'ADB flagship time-series database — macroeconomic indicators for all DMCs.', updatedAt: '30 Jun 2026' },
          ],
          actions: ['Add GDP Growth card', 'Add Debt-to-GDP card'],
        });
      },
    );
  }

  addMetricToDashboard(key: string, label: string): void {
    if (this.addedMetricKeys().has(key)) return;
    this.addedMetricKeys.update(s => new Set([...s, key]));

    const isFirst = this.ciDashboardCards().length === 0;
    if (isFirst) {
      this.ciDashboardBuilding.set(true);
      this.previewCtx.set('ci-dashboard');
      this.previewMode = 'Dashboard';
      this.cdr.markForCheck();
      setTimeout(() => {
        this.ciDashboardCards.update(cards => [...cards, { key: key as IndicatorKey, label }]);
        this.ciDashboardBuilding.set(false);
        this.cdr.markForCheck();
      }, 1600);
    } else {
      this.ciDashboardCards.update(cards => [...cards, { key: key as IndicatorKey, label }]);
      this.cdr.markForCheck();
    }
  }

  ciObs(key: IndicatorKey): KidbObs[]  { return ciObsForKey(key); }
  ciInsight(key: IndicatorKey): string | undefined {
    return CI_AI_INSIGHTS[key]?.[this.ciDashboardEconomy()];
  }
}

import {
  Component,
  ChangeDetectionStrategy,
  signal,
  inject,
  ViewChild,
  ElementRef,
  AfterViewChecked,
  OnDestroy,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router } from '@angular/router';
import { AssetCardComponent } from '../../shared/ui/asset-card/asset-card.component';
import { PromptBarComponent } from '../../shared/ui/prompt-bar/prompt-bar.component';
import { PrimaryBtnDirective } from '../../shared/ui/primary-btn/primary-btn.directive';
import { ChatService } from '../../services/chat.service';

type ConvStep = 'await-asset' | 'await-proceed' | 'await-form' | 'done';

interface ChatMsg {
  role: 'user' | 'assistant';
  text?: string;
  showSimilar?: boolean;
  showForm?: boolean;
  showSuccess?: boolean;
}

interface ContributeForm {
  title: string;
  type: string;
  description: string;
  department: string;
  contact: string;
  access: string;
  format: string;
  dataSize: string;
  rowCount: string;
  sectorGroup: string;
  geoCoverage: string;
  timePeriod: string;
  updateFreq: string;
  tags: string;
}

@Component({
  selector: 'app-contribute',
  standalone: true,
  imports: [CommonModule, FormsModule, AssetCardComponent, PromptBarComponent, PrimaryBtnDirective],
  templateUrl: './contribute.component.html',
  styleUrl: './contribute.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ContributeComponent implements AfterViewChecked, OnDestroy {
  private readonly router      = inject(Router);
  private readonly chatService = inject(ChatService);
  @ViewChild('messagesEl') private messagesEl!: ElementRef<HTMLDivElement>;

  title        = signal('Contribute an Asset');
  editingTitle = signal(false);

  messages = signal<ChatMsg[]>([{
    role: 'assistant',
    text: "Hi! I'll help you contribute a new asset to DataNext. What would you like to onboard? Describe what it is, what it contains, and how it's used.",
  }]);

  step = signal<ConvStep>('await-asset');
  thinking = signal(false);

  private historyPushed = false;
  private submittedSummary = '';

  readonly similarAssets = [
    {
      tag: 'Dataset' as const,
      tagColor: 'blue' as const,
      title: 'Climate Resilience Risk Index — Pacific SIDS',
      description: 'Composite index tracking climate vulnerability across Pacific small island developing states.',
      rating: '4.7',
      users: '892',
      downloads: '201',
      restricted: true,
    },
    {
      tag: 'Dataset' as const,
      tagColor: 'blue' as const,
      title: 'SDG Global Indicators Monitor',
      description: 'Aggregated SDG tracking metrics sourced from UN, WHO, World Bank, and ADB datasets.',
      rating: '4.5',
      users: '1.4k',
      downloads: '680',
    },
  ];

  form: ContributeForm = {
    title: '',
    type: 'Dataset',
    description: '',
    department: '',
    contact: '',
    access: 'Open Access',
    format: '',
    dataSize: '',
    rowCount: '',
    sectorGroup: '',
    geoCoverage: '',
    timePeriod: '',
    updateFreq: 'Annual',
    tags: '',
  };

  formErrors     = signal<Partial<Record<keyof ContributeForm, string>>>({});
  formDone       = signal(false);
  panelCollapsed = signal(false);
  fileAttached   = signal(false);
  attachedFileName = signal('');
  private needsScroll = false;

  onFileAttached(): void {
    this.fileAttached.set(true);
    this.attachedFileName.set('asean_water_quality_2025.parquet');
    this.form.title       = 'ASEAN Urban Water Quality Index';
    this.form.type        = 'Dataset';
    this.form.description = 'Composite monitoring dataset tracking urban water quality across ASEAN member states — turbidity, pH, dissolved oxygen, and contamination indicators from municipal systems in 47 cities.';
    this.form.department  = 'SDCC';
    this.form.contact     = 'data.products@adb.org';
    this.form.access      = 'Open Access';
    this.form.format      = 'Parquet / CSV';
    this.form.dataSize    = '2.3 GB';
    this.form.rowCount    = '4.1M';
    this.form.sectorGroup = 'Climate & Environment';
    this.form.geoCoverage = 'Southeast Asia, ASEAN';
    this.form.timePeriod  = '2010–2025';
    this.form.updateFreq  = 'Quarterly';
    this.form.tags        = 'water quality, ASEAN, urban, environment, SDG6';
  }

  clearFile(): void {
    this.fileAttached.set(false);
    this.attachedFileName.set('');
    this.form = {
      title: '', type: 'Dataset', description: '', department: '', contact: '',
      access: 'Open Access', format: '', dataSize: '', rowCount: '',
      sectorGroup: '', geoCoverage: '', timePeriod: '', updateFreq: 'Annual', tags: '',
    };
  }

  cardTagColor(type: string): 'blue' | 'violet' | 'amber' | 'teal' {
    const map: Record<string, 'blue' | 'violet' | 'amber' | 'teal'> = {
      'Dataset': 'blue', 'AI Platform': 'blue',
      'AI Agent': 'violet', 'AI Tool': 'violet',
      'Dashboard': 'amber', 'API': 'teal',
    };
    return map[type] ?? 'blue';
  }

  startEditTitle(): void { this.editingTitle.set(true); }

  saveTitle(value: string): void {
    const trimmed = value.trim();
    if (trimmed) this.title.set(trimmed);
    this.editingTitle.set(false);
  }

  private pushToHistory(): void {
    if (this.historyPushed) return;
    const msgs = this.messages();
    const hasUserMsg = msgs.some(m => m.role === 'user');
    if (!hasUserMsg) return;
    this.historyPushed = true;
    this.chatService.addContributeItem(this.title(), this.submittedSummary);
  }

  ngOnDestroy(): void { this.pushToHistory(); }

  ngAfterViewChecked(): void {
    if (this.needsScroll && this.messagesEl) {
      this.messagesEl.nativeElement.scrollTop = this.messagesEl.nativeElement.scrollHeight;
      this.needsScroll = false;
    }
  }

  private scrollToBottom(): void { this.needsScroll = true; }

  async onPrompt(text: string): Promise<void> {
    if (this.thinking()) return;
    this.messages.update(m => [...m, { role: 'user', text }]);
    this.scrollToBottom();

    this.thinking.set(true);
    await new Promise(r => setTimeout(r, 1300));
    this.thinking.set(false);

    if (this.step() === 'await-asset') {
      this.step.set('await-proceed');
      this.messages.update(m => [...m, {
        role: 'assistant',
        text: `Thanks for sharing! We already have a few assets that cover similar ground. Take a look — you may find what you need is already available:`,
        showSimilar: true,
      }]);

    } else if (this.step() === 'await-proceed') {
      const yes = /\b(yes|yep|sure|proceed|continue|still|ok|go ahead|do it)\b/i.test(text);
      if (yes) {
        this.openForm();
      } else {
        this.messages.update(m => [...m, {
          role: 'assistant',
          text: `No problem! You can explore the existing assets in the catalogue, or come back anytime to contribute something new.`,
        }]);
      }

    } else if (this.step() === 'await-form') {
      this.messages.update(m => [...m, {
        role: 'assistant',
        text: `The form is above — fill it in and hit Submit when you're ready. Let me know if you have questions about any field.`,
      }]);

    } else if (this.step() === 'done') {
      // Start a fresh contribution round
      this.form = {
        title: '', type: 'Dataset', description: '', department: '', contact: '',
        access: 'Open Access', format: '', dataSize: '', rowCount: '',
        sectorGroup: '', geoCoverage: '', timePeriod: '', updateFreq: 'Annual', tags: '',
      };
      this.formErrors.set({});
      this.formDone.set(false);
      this.step.set('await-proceed');
      this.messages.update(m => [...m, {
        role: 'assistant',
        text: `Thanks! Here are some existing assets in that area — let me know if you'd still like to proceed:`,
        showSimilar: true,
      }]);
    }

    this.scrollToBottom();
  }

  openForm(): void {
    this.step.set('await-form');
    this.messages.update(m => [...m, {
      role: 'assistant',
      text: `Great! Please fill in the details below. Fields marked * are required — Format, Size, and Rows will auto-populate when you attach the asset file.`,
      showForm: true,
    }]);
    this.scrollToBottom();
  }

  async submitForm(): Promise<void> {
    const errors: Partial<Record<keyof ContributeForm, string>> = {};
    if (!this.form.title.trim())       errors['title']       = 'Required';
    if (!this.form.description.trim()) errors['description'] = 'Required';
    this.formErrors.set(errors);
    if (Object.keys(errors).length) return;

    this.thinking.set(true);
    await new Promise(r => setTimeout(r, 1500));
    this.thinking.set(false);
    const assetTitle = this.form.title;
    this.formDone.set(true);
    this.step.set('done');
    // Auto-title the conversation after first submission if still on the default
    if (this.title() === 'Contribute an Asset') this.title.set(assetTitle);
    this.submittedSummary = `Submitted: ${assetTitle}`;
    this.historyPushed = false; // allow re-push with updated summary

    this.messages.update(m => [...m, {
      role: 'assistant',
      text: `Your asset "${assetTitle}" has been submitted for review. The data governance team will reach out to ${this.form.contact || 'you'} within 2–3 business days. You'll receive a notification once it's approved and live on DataNext. Got another asset to contribute? Just describe it below.`,
      showSuccess: true,
    }]);
    this.scrollToBottom();
  }

  close(): void {
    this.pushToHistory();
    this.router.navigate(['/notebooks'], { queryParams: { tab: 'chats' } });
  }
}

import {
