  previewCtx   = signal<PreviewCtx>('map');
  procFilter   = signal<'Active' | 'Awarded' | 'Complete' | ''>('');

  mapMarkers = signal<MapMarker[]>([]);

  // AI chain-of-thought: non-null while loading
  thinking = signal<ThinkingState | null>(null);

