  onWnSearch(q: string) {
    this.router.navigate(['/search'], q ? { queryParams: { q } } : {});
  }

  activeTab = signal<UnlocksTab>('discover');

  readonly tabs: { id: UnlocksTab; label: string }[] = [
    { id: 'discover', label: 'Discover' },
    { id: 'connect',  label: 'Connect' },
    { id: 'reuse',    label: 'Reuse' },
