:host {
  display: flex;
  flex-direction: column;
  flex: 1;
  cursor: inherit;
  container-type: inline-size;
}

:host.ac--unlisted {
  opacity: 0.45;
  filter: grayscale(0.6);
  pointer-events: none;
}

.ac__tag-row,
.ac__title,
.ac__desc {
  cursor: inherit;
}

.ac {
  &__tag-row {
    display: flex;
    align-items: center;
    gap: 6px;
    margin-bottom: 10px;
    flex-wrap: wrap;
  }

  &__tag {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    font-size: 12px;
    font-weight: 500;
    letter-spacing: 0.03em;
    padding: 3px 8px;
    border-radius: 4px;
    width: fit-content;
    flex-shrink: 0;
    font-family: var(--font, system-ui, sans-serif);

    &--blue   { background: rgba(0, 125, 183, 0.10);  color: #005F8E; }
    &--violet { background: rgba(107, 82, 210, 0.10); color: #5B3FBF; }
    &--amber  { background: rgba(217, 119, 6, 0.10);  color: #A05A00; }
    &--teal   { background: rgba(16, 185, 129, 0.10); color: #0B7A55; }
  }

  &__new-badge {
    position: absolute;
    top: 0;
    right: 0;
    background: #007DB7;
    color: #fff;
    font-size: 11px;
    font-weight: 400;
    letter-spacing: 0.04em;
    padding: 5px 12px;
    border-radius: 0 14px 0 10px;
    font-family: var(--font, system-ui, sans-serif);
    pointer-events: none;
    z-index: 1;
  }

  &__rating {
    display: inline-flex;
    align-items: center;
    gap: 3px;
    font-size: 12px;
    font-weight: 500;
    color: #6B7280;
    margin-left: auto;
    font-family: var(--font, system-ui, sans-serif);
  }

  &__toggle {
    width: 22px;
    height: 22px;
    border-radius: 50%;
    border: 1.5px solid #c9d8e4;
    background: #fff;
    color: #9e9e9e;
    display: flex;
    align-items: center;
    justify-content: center;
    cursor: pointer;
    flex-shrink: 0;
    transition: border-color 0.15s, background 0.15s, color 0.15s, transform 0.15s;

    &:hover {
      border-color: #007DB7;
      color: #007DB7;
      transform: scale(1.12);
    }

    &--on {
      border-color: #007DB7;
      background: #007DB7;
      color: #fff;
    }
  }

  &__title {
    font-size: 16px;
    font-weight: 500;
    color: #212121;
    line-height: 1.4;
    height: calc(16px * 1.4 * 2);
    margin-bottom: 8px;
    font-family: var(--font, system-ui, sans-serif);
    display: -webkit-box;
    -webkit-line-clamp: 2;
    -webkit-box-orient: vertical;
    overflow: hidden;

    [data-theme="dark"] & { color: var(--th-text, #fff); }
  }

  &__desc {
    font-size: 14px;
    font-weight: 300;
    color: #616161;
    line-height: 1.55;
    height: calc(14px * 1.55 * 3);
    margin: 0 0 20px;
    display: -webkit-box;
    -webkit-line-clamp: 3;
    -webkit-box-orient: vertical;
    overflow: hidden;
    font-family: var(--font, system-ui, sans-serif);

    [data-theme="dark"] & { color: var(--th-text-muted, #aaa); }
  }

  &__attrs {
    display: flex;
    align-items: center;
    gap: 10px;
    margin-bottom: 12px;
    min-height: 20px;
  }

  &__attr {
    display: inline-flex;
    align-items: center;
    gap: 4px;
    font-size: 12px;
    color: #9e9e9e;
    font-family: var(--font, system-ui, sans-serif);

    &--adb     { color: #6B7280; }
    &--public  { color: #059669; }
    &--rai     { color: #6366f1; }
    &--governance { color: #007DB7; }
    &--pending { color: #D97706; }
  }

  &__footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    margin-top: auto;
    padding-top: 14px;
    border-top: 1px solid #F0F0F0;
    gap: 8px;

    [data-theme="dark"] & { border-top-color: var(--th-border, #333); }
  }

  &__stats {
    display: flex;
    align-items: center;
    gap: 5px;
    flex: 1;
    min-width: 0;
  }

  &__stat {
    display: inline-flex;
    align-items: center;
    gap: 3px;
    font-size: 12px;
    color: #9e9e9e;
    white-space: nowrap;
    font-family: var(--font, system-ui, sans-serif);
  }

  &__stat-sep {
    font-size: 12px;
    color: #c8c8c8;
  }

  &__stat-label {
    @container (max-width: 260px) {
      display: none;
    }
  }

  &__actions {
    display: flex;
    gap: 2px;
    flex-shrink: 0;
    margin-left: auto;
  }

  &__action-btn {
    position: relative;
    width: 28px;
    height: 28px;
    border: none;
    background: none;
    cursor: pointer;
    border-radius: 6px;
    display: flex;
    align-items: center;
    justify-content: center;
    color: #007DB7;
    transition: background 0.15s, color 0.15s;

    &:hover { background: rgba(0, 125, 183, 0.10); }

    &--selected {
      color: #007DB7;
      background: rgba(0, 125, 183, 0.10);
    }

    &--saved { color: #007DB7; }

    &[data-tooltip] {
      &::before,
      &::after {
        position: absolute;
        bottom: calc(100% + 5px);
        left: 50%;
        transform: translateX(-50%);
        pointer-events: none;
        opacity: 0;
        transition: opacity 0.15s;
        z-index: 20;
      }

      &::after {
        content: attr(data-tooltip);
        background: #1a1a1a;
        color: #fff;
        font-size: 11px;
        font-weight: 400;
        font-family: var(--font, system-ui, sans-serif);
        padding: 4px 8px;
        border-radius: 5px;
        white-space: nowrap;
        letter-spacing: 0.01em;
      }

      &::before {
        content: '';
        bottom: calc(100% + 1px);
        border: 4px solid transparent;
        border-top-color: #1a1a1a;
      }

      &:hover::before,
      &:hover::after { opacity: 1; }
    }
  }
}

