interface AssetVersion {
  version: string;
  releaseDate: string;
  author: string;
  summary: string;
  changes: string[];
  size?: string;
}

interface TableRow {
  label: string;
  value: string;
  isLink?: boolean;
}

type AccessLevel = 'Open' | 'Restricted' | 'Limited';

interface AccessEntry {
  id: number;
  name: string;
  email: string;
  type: 'user' | 'group';
  role: 'Viewer' | 'Editor';
  addedDate: string;
}

interface AccessRequest {
  id: number;
  name: string;
  email: string;
  department: string;
  requestedDate: string;
  reason: string;
}

interface ViewerColumn { name: string; type: string; }
interface ViewerImage { label: string; sublabel?: string; src: string; meta?: string; }

interface RelatedAsset {
  title: string;
  tag: string;
  tagColor: 'blue' | 'violet' | 'amber' | 'teal';
  description: string;
  rating: string;
  users: string;
  downloads: string;
