:host {
  display: block;
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: var(--ia-aurora-height, 280px);
  pointer-events: none;
  overflow: hidden;
  z-index: 0;
  -webkit-mask-image: linear-gradient(to right, transparent 0%, black 8%, black 92%, transparent 100%);
  mask-image: linear-gradient(to right, transparent 0%, black 8%, black 92%, transparent 100%);
}

.stripe {
  position: absolute;
  top: 0;
  left: 0;
  right: 0;
  height: 2px;
  z-index: 2;
  animation: stripe-sweep 2.5s linear infinite;
}

.blob {
  position: absolute;
  top: -30%;
  width: 70%;
  height: 160%;
  border-radius: 50%;
  filter: blur(70px);
  will-change: transform, opacity;
}

:host.aurora--green {
  .stripe {
    background: linear-gradient(
      90deg,
      rgba(255, 255, 255, 0)   0%,
      #007db7                 36%,
      #8dc63f                 79%,
      rgba(255, 255, 255, 0) 100%
    );
  }
  .blob-a {
    background: radial-gradient(ellipse, rgba(0, 125, 183, 0.32) 0%, transparent 70%);
    animation: blob-a-green 8s ease-in-out infinite;
  }
  .blob-b {
    background: radial-gradient(ellipse, rgba(141, 198, 63, 0.32) 0%, transparent 70%);
    animation: blob-b-green 8s ease-in-out infinite;
  }
}

:host.aurora--purple {
  .stripe {
    background: linear-gradient(
      90deg,
      rgba(255, 255, 255, 0.00)  0%,
      rgba(104, 197, 234, 0.50) 36%,
      rgba(174,  93, 237, 0.50) 79%,
      rgba(255, 255, 255, 0.00) 100%
    );
    animation-duration: 5s;
    animation-timing-function: ease-in-out;
  }
  .blob-a {
    background: radial-gradient(ellipse, rgba(104, 197, 234, 0.45) 0%, transparent 70%);
    animation: blob-a-purple 12s ease-in-out infinite;
  }
  .blob-b {
    background: radial-gradient(ellipse, rgba(174, 93, 237, 0.40) 0%, transparent 70%);
    animation: blob-b-purple 12s ease-in-out infinite;
  }
}

@keyframes stripe-sweep {
  from { transform: translateX(-100%); }
  to   { transform: translateX(100%); }
}
@keyframes blob-a-green {
  0%   { left: -5%; opacity: 0.90; transform: scaleX(0.92); }
  50%  { left: 20%; opacity: 0.72; transform: scaleX(1.06); }
  100% { left: -5%; opacity: 0.90; transform: scaleX(0.92); }
}
@keyframes blob-b-green {
  0%   { left: 30%; opacity: 0.80; transform: scaleX(1.05); }
  50%  { left: 5%;  opacity: 0.65; transform: scaleX(0.92); }
  100% { left: 30%; opacity: 0.80; transform: scaleX(1.05); }
}
@keyframes blob-a-purple {
  0%   { left: -5%; opacity: 0.58; transform: scaleX(0.92); }
  50%  { left: 20%; opacity: 0.42; transform: scaleX(1.06); }
  100% { left: -5%; opacity: 0.58; transform: scaleX(0.92); }
}
@keyframes blob-b-purple {
  0%   { left: 30%; opacity: 0.50; transform: scaleX(1.05); }
  50%  { left: 5%;  opacity: 0.35; transform: scaleX(0.92); }
  100% { left: 30%; opacity: 0.50; transform: scaleX(1.05); }
}
@media (prefers-reduced-motion: reduce) {
  .stripe, .blob { animation: none; }
}

