      let label = 'Results';
      if (!query) {
        if (type !== 'All' && dept !== 'All') {
          label = `${type}s · ${dept}`;
        } else if (type !== 'All') {
          label = `${type}s`;
        } else if (dept !== 'All') {
          label = `${dept} Assets`;
        }
      }

      return [{ label, type: '', items: this.filtered() }];
