import {
  Component, computed, inject, signal, ElementRef, ViewChild, OnInit
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { ActivatedRoute, Router } from '@angular/router';
import { ChatService, summarizeTitle } from '../../services/chat.service';
import { PromptBarComponent } from '../../shared/ui/prompt-bar/prompt-bar.component';

export interface ChatTurn {
  role: 'user' | 'ai';
  text: string;
}

@Component({
  selector: 'app-chat-view',
  standalone: true,
  imports: [CommonModule, FormsModule, PromptBarComponent],
  templateUrl: './chat-view.component.html',
  styleUrl: './chat-view.component.scss',
})
export class ChatViewComponent implements OnInit {
  private readonly route  = inject(ActivatedRoute);
  private readonly router = inject(Router);
  readonly chatService    = inject(ChatService);

  chatId = '';

  readonly item = computed(() =>
    this.chatService.history().find(h => h.id === this.chatId) ?? null
  );

  readonly displayTitle = computed(() => {
    const i = this.item();
    if (!i) return '';
    return i.title || summarizeTitle(i.question);
  });

  editing   = false;
  editValue = '';

  // Additional turns added via follow-up
  followUpTurns = signal<ChatTurn[]>([]);

  @ViewChild('titleInput') titleInputRef?: ElementRef<HTMLInputElement>;

  ngOnInit() {
    this.chatId = this.route.snapshot.paramMap.get('id') ?? '';
  }

  startEdit() {
    this.editValue = this.displayTitle();
    this.editing = true;
    setTimeout(() => this.titleInputRef?.nativeElement.select());
  }

  commitEdit() {
    const trimmed = this.editValue.trim();
    if (trimmed && trimmed !== this.displayTitle()) {
      this.chatService.updateTitle(this.chatId, trimmed);
    }
    this.editing = false;
  }

  cancelEdit() { this.editing = false; }

  onTitleKeydown(e: KeyboardEvent) {
    if (e.key === 'Enter')  { e.preventDefault(); this.commitEdit(); }
    if (e.key === 'Escape') { this.cancelEdit(); }
  }

  sendFollowUp(text: string) {
    if (!text.trim()) return;
    this.followUpTurns.update(turns => [
      ...turns,
      { role: 'user', text },
      { role: 'ai',   text: 'Follow-up responses are coming soon in this view.' },
    ]);
  }

  goBack() { this.router.navigate(['/home']); }
}

