    line-height: 1.5;
  }

  &__msg-avatar {
    width: 36px;
    height: 36px;
    border-radius: 50%;
    background: #007DB7;
    color: #fff;
    font-size: 14px;
    font-weight: 500;
    font-family: var(--font, system-ui, sans-serif);
    display: flex;
    align-items: center;
    justify-content: center;
    flex-shrink: 0;
  }

  &__msg-text {
    margin: 0;
    font-size: 14px;
    color: #212121;
    font-family: var(--font, system-ui, sans-serif);
    line-height: 1.5;
  }

  // ── Thinking dots ─────────────────────────────────────────────────────────
  &__thinking-dots {
    display: flex;
    align-items: center;
    gap: 4px;
    padding: 8px 0;

    span {
      display: inline-block;
      width: 7px;
      height: 7px;
      border-radius: 50%;
      background: #bdbdbd;
      animation: contribDot 1.4s ease infinite;
    }
  }

  // ── Similar assets ────────────────────────────────────────────────────────
  &__msg-widgets {
    display: grid;
    grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
    gap: 12px;
  }

  &__widget-card {
    border: 1px solid #e8e8e8;
    border-radius: 12px;
    padding: 16px;
    background: #fff;
    display: flex;
    flex-direction: column;
    cursor: default;
    transition: box-shadow 0.15s;

    &:hover { box-shadow: 0 2px 12px rgba(0, 0, 0, 0.06); }
  }

  // ── Action pills ──────────────────────────────────────────────────────────
  &__actions {
    display: flex;
    flex-wrap: wrap;
    gap: 6px;
  }

  &__action-btn {
    display: inline-flex;
    align-items: center;
    height: 30px;
    padding: 0 14px;
    background: #fff;
    border: 1px solid #e0e0e0;
    border-radius: 999px;
    font-size: 12.5px;
    color: #424242;
    font-family: var(--font, system-ui, sans-serif);
    cursor: pointer;
    white-space: nowrap;
    transition: background 0.12s, border-color 0.12s, color 0.12s;

    &:hover {
      background: #F0F7FB;
      border-color: #007DB7;
      color: #007DB7;
    }
  }

  // ── Inline form widget ────────────────────────────────────────────────────
  &__form-widget {
    border: 1px solid #e8e8e8;
    border-radius: 12px;
    background: #fff;
    overflow: hidden;
  }

  &__form-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px 20px;
    padding: 24px;
  }

  &__field {
    display: flex;
    flex-direction: column;
    gap: 5px;

    &--full { grid-column: 1 / -1; }
  }

  &__field-label {
    font-size: 12px;
    font-weight: 500;
    color: #616161;
    font-family: var(--font, system-ui, sans-serif);
    display: flex;
    align-items: center;
    gap: 6px;
  }

  &__field-auto {
    font-size: 10.5px;
    font-weight: 400;
    color: #9e9e9e;
    background: #f5f5f5;
    border-radius: 4px;
    padding: 1px 6px;
  }

  &__field-err {
    font-size: 11.5px;
    color: #e53935;
    font-family: var(--font, system-ui, sans-serif);
  }

  &__input,
  &__select,
  &__textarea {
    font-size: 13.5px;
    font-family: var(--font, system-ui, sans-serif);
    color: #212121;
    background: #fafafa;
    border: 1px solid #e0e0e0;
    border-radius: var(--radius-ctrl);
    padding: 8px 10px;
    outline: none;
    transition: border-color 0.15s, background 0.15s;

    &:focus {
      border-color: #007DB7;
      background: #fff;
    }

    &--error { border-color: #e53935; }
  }

  &__textarea {
    resize: vertical;
    min-height: 72px;
    line-height: 1.5;
  }

  &__select { cursor: pointer; }

  &__upload-zone {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 8px;
    padding: 28px 24px;
    margin: 20px 20px 0;
    border: 2px dashed #c8d8e4;
    border-radius: 10px;
    background: #f8fafc;
    cursor: pointer;
    text-align: center;
    user-select: none;
    transition: border-color 0.15s, background 0.15s;

    &:hover {
      border-color: #007DB7;
      background: rgba(0, 125, 183, 0.04);
    }

    &--attached {
      flex-direction: row;
      padding: 14px 20px;
      border-style: solid;
      border-color: #10b981;
      background: rgba(16, 185, 129, 0.05);
      cursor: default;
      text-align: left;

      &:hover { border-color: #10b981; background: rgba(16, 185, 129, 0.05); }
    }
  }

  &__upload-zone-title {
    font-size: 13.5px;
    font-weight: 500;
    color: #212121;
    font-family: var(--font, system-ui, sans-serif);
  }

  &__upload-zone-sub {
    font-size: 12px;
    color: #9e9e9e;
    font-family: var(--font, system-ui, sans-serif);
  }

  &__upload-zone-file {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 3px;
    margin-left: 10px;
  }

  &__upload-zone-filename {
    font-size: 14px;
    font-weight: 500;
    color: #212121;
    font-family: var(--font, system-ui, sans-serif);
    overflow: hidden;
    text-overflow: ellipsis;
    white-space: nowrap;
  }

  &__upload-zone-change {
    flex-shrink: 0;
    background: none;
    border: 1px solid #d0d8e0;
    border-radius: var(--radius-ctrl);
    padding: 4px 12px;
    font-size: 12px;
    color: #616161;
    font-family: var(--font, system-ui, sans-serif);
    cursor: pointer;
    transition: border-color 0.12s, color 0.12s;
    white-space: nowrap;

    &:hover { border-color: #007DB7; color: #007DB7; }
  }

  &__upload-row {
    display: flex;
    align-items: center;
    gap: 12px;
    padding: 14px 24px;
    border-top: 1px solid #f0f0f0;
  }

  &__upload-btn {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    height: 32px;
    padding: 0 12px;
    border: 1.5px dashed #c5d5de;
    border-radius: var(--radius-ctrl);
    font-size: 12.5px;
    color: #007DB7;
    font-family: var(--font, system-ui, sans-serif);
    cursor: pointer;
    transition: border-color 0.15s, background 0.15s;

    &:hover { border-color: #007DB7; background: #F0F7FB; }
  }

  &__upload-hint {
    font-size: 11.5px;
    color: #9e9e9e;
    font-family: var(--font, system-ui, sans-serif);
  }

  &__form-footer {
    display: flex;
    justify-content: flex-end;
    padding: 14px 24px;
    border-top: 1px solid #f0f0f0;
  }


  // ── Success badge ─────────────────────────────────────────────────────────
  &__success {
    display: inline-flex;
    align-items: center;
    gap: 7px;
    padding: 8px 14px;
    background: #E8F5E9;
    border: 1px solid #C8E6C9;
    border-radius: 8px;
    font-size: 14px;
    font-weight: 500;
    color: #2E7D32;
    font-family: var(--font, system-ui, sans-serif);
    align-self: flex-start;
  }

  // ── Input bar ─────────────────────────────────────────────────────────────
  &__input-bar {
    padding: 12px 24px 24px;
    flex-shrink: 0;
    max-width: 768px;
    width: 100%;
    align-self: center;

    ::ng-deep .search-input {
      box-shadow: rgba(141, 198, 63, 0.15) 0 0 20px 0;
    }
  }

  // ── Review panel ──────────────────────────────────────────────────────────
  &__review-panel {
    width: clamp(340px, 36%, 480px);
    flex-shrink: 0;
    border-left: 1px solid #f0f0f0;
    overflow-y: auto;
    padding: 0;
    display: flex;
    flex-direction: column;
    scrollbar-width: none;
    animation: contribPanelIn 0.28s ease both;

    &::-webkit-scrollbar { display: none; }

    @media (max-width: 900px) {
      width: 100%;
      border-left: none;
      border-top: 1px solid #f0f0f0;
      max-height: 50vh;
    }
  }

  &__status-section {
    padding: 20px 20px 16px;
    border-bottom: 1px solid #f0f0f0;
    flex-shrink: 0;
  }

  &__details-section {
    flex: 1;
    overflow-y: auto;
    display: flex;
    flex-direction: column;
    scrollbar-width: none;

    &::-webkit-scrollbar { display: none; }
  }

  &__details-header {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding: 14px 20px;
    cursor: pointer;
    flex-shrink: 0;
    user-select: none;
    transition: background 0.12s;

    &:hover { background: #fafafa; }
  }

  &__section-title {
    font-size: 14px;
    font-weight: 500;
    color: #212121;
    font-family: var(--font, system-ui, sans-serif);
    letter-spacing: 0.01em;
  }

  &__panel-chevron {
    color: #9e9e9e;
    transition: transform 0.2s ease;
    flex-shrink: 0;

    &--up { transform: rotate(180deg); }
  }

  // ── Stepper (dashed circles, horizontal) ──────────────────────────────────
  &__stepper {
    display: flex;
    align-items: flex-start;
    padding: 20px 20px 16px;
  }

  &__step {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 8px;
    flex-shrink: 0;
  }

  &__step-node {
    width: 40px;
    height: 40px;
    border-radius: 50%;
    display: flex;
    align-items: center;
    justify-content: center;

    &--done {
      border: 2px dashed #007DB7;
      color: #007DB7;
      background: rgba(0, 125, 183, 0.06);
    }

    &--active {
      background: #0a4d8c;
      border: 2px solid #0a4d8c;
      color: #fff;
    }

    &--pending {
      border: 2px dashed #c8c8c8;
      color: #c8c8c8;
      background: transparent;
    }
  }

  &__step-connector {
    flex: 1;
    height: 0;
    border-top: 1.5px dashed #d0d0d0;
    margin-top: 20px;
    align-self: flex-start;

    &--done { border-top-color: #007DB7; }
  }

  &__step-label {
    font-size: 12px;
    font-weight: 500;
    color: #212121;
    font-family: var(--font, system-ui, sans-serif);
    text-align: center;
    white-space: nowrap;

    .contrib__step--active & { color: #0a4d8c; }
    .contrib__step:not(.contrib__step--done):not(.contrib__step--active) & { color: #9e9e9e; }
  }

  &__step-sub {
    font-size: 12px;
    color: #9e9e9e;
    font-family: var(--font, system-ui, sans-serif);
    text-align: center;
    white-space: nowrap;
    font-style: italic;
  }

  // ── Panel asset title / description ───────────────────────────────────────
  &__panel-asset {
    padding: 16px 20px 12px;
    border-bottom: 1px solid #f5f5f5;
  }

  &__asset-title {
    font-size: 16px;
    font-weight: 500;
    color: #212121;
    font-family: var(--font, system-ui, sans-serif);
    margin: 0 0 6px;
    line-height: 1.4;
  }

  &__asset-desc {
    font-size: 14px;
    font-weight: 300;
    color: #616161;
    font-family: var(--font, system-ui, sans-serif);
    margin: 0;
    line-height: 1.55;
    display: -webkit-box;
    -webkit-line-clamp: 4;
    -webkit-box-orient: vertical;
    overflow: hidden;
  }

  // ── Metadata grid ─────────────────────────────────────────────────────────
  &__meta-grid {
    display: grid;
    grid-template-columns: 1fr 1fr;
    gap: 16px 12px;
    padding: 16px 20px 24px;
  }

  &__meta-cell {
    display: flex;
    flex-direction: column;
    gap: 4px;
    min-width: 0;

    &--full { grid-column: 1 / -1; }
  }

  &__meta-label {
    font-size: 14px;
    color: #9e9e9e;
    font-weight: 400;
    font-family: var(--font, system-ui, sans-serif);
  }

  &__meta-value {
    font-size: 14px;
    color: #212121;
    font-weight: 400;
    font-family: var(--font, system-ui, sans-serif);
    line-height: 1.4;
    word-break: break-word;

    &--empty { color: #c8c8c8; }
  }
}

// ── Animations ────────────────────────────────────────────────────────────────

@keyframes contribMsgIn {
  from { opacity: 0; transform: translateY(10px); }
  to   { opacity: 1; transform: translateY(0); }
}

@keyframes contribDot {
  0%, 80%, 100% { transform: scale(0.8); opacity: 0.4; }
  40%           { transform: scale(1);   opacity: 1; }
}

@keyframes contribPanelIn {
  from { opacity: 0; transform: translateX(16px); }
  to   { opacity: 1; transform: translateX(0); }
}

@keyframes contribPulse {
  0%, 100% { transform: scale(0.85); opacity: 0.6; }
  50%       { transform: scale(1.15); opacity: 1; }
}

