:host {
  display: flex;
  flex-direction: column;
  flex: 1;
  min-width: 0;
  height: 100vh;
  overflow: hidden;
}

.explorer {
  display: flex;
  flex-direction: column;
  flex: 1;
  height: 100%;
  overflow: hidden;
}

/* ── Title bar ────────────────────────────────────────────────────────────── */
.explorer__titlebar {
  height: 56px;
  flex-shrink: 0;
  width: 100%;
  display: flex;
  align-items: stretch;
  background: var(--th-card);
  border-bottom: 1px solid var(--th-border);
}

.explorer__titlebar-left {
  flex: 1;
  min-width: 0;
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 0 16px;
}

.explorer__titlebar-right {
  width: 45%;
  flex-shrink: 0;
  display: flex;
  align-items: center;
  gap: 10px;
  padding: 0 16px;
  border-left: 1px solid var(--th-border);
}

.explorer__titlebar-spacer {
  width: 40px;
  flex-shrink: 0;
}

.explorer__title-wrap {
  flex: 1;
  display: flex;
  justify-content: center;
  overflow: hidden;
  padding: 0 8px;
}

.explorer__title-btn {
  background: none;
  border: none;
  cursor: pointer;
  font-size: 14px;
  font-weight: 500;
  color: var(--th-text);
  font-family: var(--font);
  max-width: 520px;
  white-space: nowrap;
  overflow: hidden;
  text-overflow: ellipsis;

  &:hover { color: var(--adb-blue); }
}

.explorer__title-input {
  font-size: 14px;
  font-weight: 500;
  text-align: center;
  background: transparent;
  border: none;
  outline: none;
  color: var(--th-text);
  width: 100%;
  max-width: 520px;
  font-family: var(--font);
  border-bottom: 1px solid var(--adb-blue);
}

.explorer__titlebar-actions {
  display: flex;
  align-items: center;
  gap: 4px;
  width: 40px;
  justify-content: flex-end;
}

.explorer__titlebar-btn {
  background: none;
  border: none;
  cursor: pointer;
  padding: 6px;
  border-radius: 6px;
  color: var(--th-muted);
  display: flex;
  align-items: center;
  transition: background 0.12s, color 0.12s;

  &:hover {
    background: color-mix(in srgb, var(--th-text) 6%, transparent);
    color: var(--th-text);
  }
}

.explorer__pdf-title-text {
  flex: 1;
  font-size: 14px;
  font-weight: 500;
  color: var(--th-text);
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

/* ── Body layout ─────────────────────────────────────────────────────────── */
.explorer__body {
  flex: 1;
  display: flex;
  min-height: 0;
  overflow: hidden;
}

/* ── Chat panel ──────────────────────────────────────────────────────────── */
.explorer__chat-panel {
  flex: 1;
  display: flex;
  flex-direction: column;
  min-width: 0;
  min-height: 0;

  &--with-pdf {
    width: 45%;
    flex: none;
    border-right: 1px solid var(--th-border);
  }
}

/* ── Messages ────────────────────────────────────────────────────────────── */
.explorer__messages {
  flex: 1;
  overflow-y: auto;
  padding: 24px 24px 0;
  display: flex;
  flex-direction: column;
  gap: 20px;
  min-height: 0;
}

/* ── Empty state ─────────────────────────────────────────────────────────── */
.explorer__empty {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: 48px 24px 24px;
}

.explorer__empty-sparkle {
  margin-bottom: 16px;
  width: 52px;
  height: 52px;
  border-radius: 50%;
  background: color-mix(in srgb, var(--adb-blue) 10%, transparent);
  display: flex;
  align-items: center;
  justify-content: center;
}

.explorer__empty-title {
  font-size: 22px;
  font-weight: 500;
  color: var(--th-text);
  margin-bottom: 8px;
}

.explorer__empty-desc {
  font-size: 14px;
  color: var(--th-muted);
  max-width: 420px;
  line-height: 1.6;
  margin-bottom: 32px;
}

.explorer__suggestions {
  display: flex;
  flex-direction: column;
  gap: 6px;
  width: 100%;
  max-width: 560px;
}

.explorer__suggestion {
  width: 100%;
  padding: 10px 14px;
  background: var(--th-card);
  border: 1px solid var(--th-border);
  border-radius: 10px;
  cursor: pointer;
  font-size: 14px;
  color: var(--th-text);
  font-family: var(--font);
  text-align: left;
  transition: border-color 0.12s, background 0.12s;

  &:hover {
    border-color: var(--adb-blue);
    background: color-mix(in srgb, var(--adb-blue) 5%, transparent);
  }
}

/* ── Message bubbles ─────────────────────────────────────────────────────── */
.explorer__msg {
  display: flex;
  max-width: 760px;
  width: 100%;

  &--user {
    justify-content: flex-end;
    margin-left: auto;
  }

  &--assistant {
    align-items: flex-start;
    gap: 10px;
  }
}

.explorer__msg-avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  background: color-mix(in srgb, var(--adb-blue) 12%, transparent);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  margin-top: 2px;
}

.explorer__msg-bubble {
  &--user {
    background: var(--adb-blue);
    color: #fff;
    padding: 10px 16px;
    border-radius: 18px 18px 4px 18px;
    font-size: 14px;
    line-height: 1.6;
    max-width: 80%;
  }
}

.explorer__msg-content {
  flex: 1;
  min-width: 0;
}

.explorer__msg-text {
  font-size: 14px;
  color: var(--th-text);
  line-height: 1.8;
  font-weight: 300;
  white-space: pre-wrap;
}

.explorer__msg-actions {
  display: flex;
  align-items: center;
  gap: 6px;
  margin-top: 10px;
}

.explorer__msg-action {
  background: none;
  border: none;
  cursor: pointer;
  padding: 5px;
  border-radius: 6px;
  color: var(--th-muted);
  display: flex;
  align-items: center;
  transition: background 0.12s, color 0.12s;

  &:hover {
    background: color-mix(in srgb, var(--th-text) 6%, transparent);
    color: var(--th-text);
  }
}

.explorer__source-chip {
  font-size: 12px;
  padding: 3px 10px;
  border-radius: 20px;
  border: 1px solid var(--th-border);
  background: var(--th-card);
  color: var(--adb-blue);
  cursor: pointer;
  font-family: var(--font);
  transition: border-color 0.12s;

  &:hover {
    border-color: var(--adb-blue);
  }
}

/* ── Loading dots ────────────────────────────────────────────────────────── */
.explorer__dots {
  display: flex;
  gap: 6px;
  align-items: center;
  padding: 4px 0;

  span {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: var(--adb-blue);
    animation: pulse 1.2s ease-in-out infinite;
    display: inline-block;
  }
}

/* ── Input bar ────────────────────────────────────────────────────────────── */
.explorer__input-wrap {
  flex-shrink: 0;
  padding: 12px 24px 16px;
  border-top: 1px solid var(--th-border);
  background: var(--th-bg);
}

.explorer__input-form {
  margin: 0;
}

.explorer__input-bar {
  display: flex;
  align-items: center;
  gap: 8px;
  background: var(--th-card);
  border: 1px solid var(--th-border);
  border-radius: 14px;
  padding: 10px 10px 10px 14px;
  transition: border-color 0.15s;

  &:focus-within {
    border-color: var(--adb-blue);
  }
}

.explorer__input-clip {
  background: none;
  border: none;
  cursor: pointer;
  padding: 6px;
  color: var(--th-muted);
  display: flex;
  align-items: center;
  flex-shrink: 0;

  &:hover { color: var(--th-text); }
}

.explorer__input {
  flex: 1;
  background: none;
  border: none;
  outline: none;
  color: var(--th-text);
  font-size: 14px;
  font-family: var(--font);

  &::placeholder { color: var(--th-muted); }
}

.explorer__send {
  width: 36px;
  height: 36px;
  border-radius: 50%;
  flex-shrink: 0;
  background: color-mix(in srgb, var(--th-text) 14%, transparent);
  border: none;
  cursor: default;
  color: var(--th-muted);
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.2s, color 0.2s;

  &--active {
    background: var(--adb-blue);
    color: #fff;
    cursor: pointer;

    &:hover {
      background: color-mix(in srgb, var(--adb-blue) 85%, #000);
    }
  }
}

.explorer__input-disclaimer {
  font-size: 12px;
  color: var(--th-muted);
  text-align: center;
  margin-top: 8px;
}

/* ── Citation sidebar ────────────────────────────────────────────────────── */
.explorer__citations {
  width: 300px;
  flex-shrink: 0;
  border-left: 1px solid var(--th-border);
  display: flex;
  flex-direction: column;
  background: var(--th-card);
}

.explorer__citations-header {
  height: 48px;
  padding: 0 16px;
  display: flex;
  align-items: center;
  justify-content: space-between;
  border-bottom: 1px solid var(--th-border);
  flex-shrink: 0;
}

.explorer__citations-title {
  font-size: 14px;
  font-weight: 500;
  color: var(--th-text);
}

.explorer__citations-close {
  background: none;
  border: none;
  cursor: pointer;
  padding: 4px;
  color: var(--th-muted);
  display: flex;
  align-items: center;
  border-radius: 4px;

  &:hover {
    background: color-mix(in srgb, var(--th-text) 6%, transparent);
    color: var(--th-text);
  }
}

.explorer__citations-list {
  flex: 1;
  overflow-y: auto;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 10px;
}

.explorer__citation-card {
  background: var(--th-bg);
  border: 1px solid var(--th-border);
  border-radius: 8px;
  padding: 12px 14px;
  cursor: pointer;
  transition: border-color 0.12s, box-shadow 0.12s;

  &:hover {
    border-color: var(--adb-blue);
    box-shadow: 0 2px 12px rgba(0, 125, 183, 0.1);
  }
}

.explorer__citation-top {
  display: flex;
  justify-content: space-between;
  align-items: center;
  margin-bottom: 6px;
}

.explorer__citation-type {
  font-size: 10px;
  font-weight: 500;
  color: var(--adb-blue);
  text-transform: uppercase;
  letter-spacing: 0.06em;
}

.explorer__citation-date {
  font-size: 12px;
  color: var(--th-muted);
}

.explorer__citation-title {
  font-size: 14px;
  font-weight: 500;
  color: var(--th-text);
  line-height: 1.35;
  margin-bottom: 4px;
}

.explorer__citation-sub {
  font-size: 12px;
  color: var(--th-muted);
  margin-bottom: 6px;
}

.explorer__citation-page {
  display: inline-flex;
  align-items: center;
  font-size: 12px;
  color: var(--adb-blue);
  background: color-mix(in srgb, var(--adb-blue) 10%, transparent);
  border-radius: 20px;
  padding: 2px 9px;
}

/* ── PDF panel ────────────────────────────────────────────────────────────── */
.explorer__pdf-panel {
  width: 55%;
  flex-shrink: 0;
  border-left: 1px solid var(--th-border);
  display: flex;
  flex-direction: column;
  background: var(--th-bg);
}

.explorer__pdf-nav {
  height: 44px;
  flex-shrink: 0;
  padding: 0 16px;
  border-bottom: 1px solid var(--th-border);
  display: flex;
  align-items: center;
  gap: 6px;
  background: var(--th-card);
}

.explorer__pdf-btn {
  background: none;
  border: none;
  cursor: pointer;
  padding: 4px;
  display: flex;
  align-items: center;
  color: var(--adb-blue);
  text-decoration: none;

  &:disabled {
    opacity: 0.3;
    cursor: default;
  }
}

.explorer__pdf-page {
  font-size: 12px;
  color: var(--th-muted);
  display: flex;
  align-items: center;
  gap: 5px;
}

.explorer__pdf-page-input {
  width: 36px;
  padding: 2px 4px;
  text-align: center;
  background: var(--th-bg);
  border: 1px solid var(--th-border);
  border-radius: 4px;
  color: var(--th-text);
  font-size: 12px;
  outline: none;
  font-family: var(--font);
}

.explorer__pdf-spacer { flex: 1; }

.explorer__pdf-body {
  flex: 1;
  overflow: auto;
  background: color-mix(in srgb, var(--th-text) 8%, transparent);
  display: flex;
  justify-content: center;
  padding: 24px 16px;
}

.explorer__pdf-placeholder {
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  gap: 12px;
  padding-top: 32px;
}

.explorer__pdf-placeholder-title {
  font-size: 15px;
  font-weight: 500;
  color: var(--th-text);
}

.explorer__pdf-placeholder-sub {
  font-size: 14px;
  color: var(--th-muted);
}

.explorer__pdf-link {
  font-size: 14px;
  color: var(--adb-blue);
  display: inline-flex;
  align-items: center;
  gap: 4px;

  &:hover { text-decoration: underline; }
}

:host {
  display: inline-flex;
  align-items: center;
  justify-content: center;
}

