import { Component, ChangeDetectionStrategy, signal, computed, inject, OnInit } from '@angular/core';
import { CommonModule } from '@angular/common';
import { FormsModule } from '@angular/forms';
import { Router, ActivatedRoute } from '@angular/router';
import { ChatService } from '../../services/chat.service';
import { AssetCardComponent } from '../../shared/ui/asset-card/asset-card.component';
import { PrimaryBtnDirective } from '../../shared/ui/primary-btn/primary-btn.directive';

export interface WorkspaceCard {
  id: string;
  title: string;
  description: string;
  image: string;
  datasets: number;
  platforms: number;
  tools: number;
  status: 'draft' | 'published';
  region?: string;
  author?: string;
  keyAssets?: string[];
}

export interface RecentItem {
  id: string;
  title: string;
  type: string;
  typeColor: 'blue' | 'violet' | 'amber' | 'teal' | 'rose';
  accessedAt: string;
  icon: 'dataset' | 'agent' | 'dashboard' | 'api' | 'notebook';
  description?: string;
  rating?: string;
  users?: string;
  downloads?: string;
  restricted?: boolean;
  image?: string;
}

export interface ContributionItem {
  id: string;
  title: string;
  description: string;
  type: string;
  typeColor: 'blue' | 'violet' | 'amber' | 'teal';
  status: 'published' | 'pending' | 'draft';
  downloads: number;
  uploadedAt: string;
  slug?: string;
