    font-family: var(--font, system-ui, sans-serif);
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
  }

  &__recent-type {
    font-size: 12px;
    font-weight: 500;
    padding: 2px 7px;
    border-radius: 4px;
    white-space: nowrap;
    flex-shrink: 0;

    &--blue   { background: rgba(0, 125, 183, 0.10);  color: #005F8E; }
    &--violet { background: rgba(107, 82, 210, 0.10); color: #5B3FBF; }
    &--amber  { background: rgba(217, 119, 6, 0.10);  color: #A05A00; }
    &--teal   { background: rgba(16, 185, 129, 0.10); color: #0B7A55; }
    &--rose   { background: rgba(71, 85, 105, 0.10);  color: #475569; }
  }

  &__recent-time {
    font-size: 12px;
    color: #9e9e9e;
    font-family: var(--font, system-ui, sans-serif);
    white-space: nowrap;
    flex-shrink: 0;
  }

  // ── Contributions ─────────────────────────────────────────────────────────
  &__contrib-list {
    display: flex;
    flex-direction: column;
    gap: 10px;
  }

  &__contrib-card {
    display: flex;
    background: #fff;
    border: 1px solid #ebebeb;
    border-radius: 12px;
    overflow: hidden;
    box-shadow: 0 1px 3px rgba(12, 35, 60, 0.04);
    transition: box-shadow 0.18s ease, border-color 0.18s ease;

    &:hover { box-shadow: 0 4px 14px rgba(12, 35, 60, 0.09); border-color: #d8e4ef; }
  }

  &__contrib-accent {
    width: 4px;
    flex-shrink: 0;

    &--published { background: #10b981; }
    &--pending   { background: #f59e0b; }
    &--draft     { background: #cbd5e1; }
  }

  &__contrib-body {
    flex: 1;
    display: flex;
    flex-direction: column;
    padding: 16px 20px;
    gap: 12px;
    min-width: 0;
  }

  &__contrib-main {
    display: flex;
    align-items: flex-start;
    gap: 16px;
  }

  &__contrib-info {
    flex: 1;
    min-width: 0;
    display: flex;
    flex-direction: column;
    gap: 6px;
  }

  &__contrib-header {
    display: flex;
    align-items: center;
    gap: 8px;
  }

  &__contrib-status {
    font-size: 12px;
    font-weight: 500;
    padding: 2px 8px;
    border-radius: 20px;
    text-transform: capitalize;

    &--published { background: rgba(16, 185, 129, 0.12); color: #065F46; }
    &--pending   { background: rgba(245, 158, 11, 0.12); color: #92400e; }
    &--draft     { background: rgba(0, 0, 0, 0.06);       color: #757575; }
  }

  &__contrib-title {
    margin: 0;
    font-size: 15px;
    font-weight: 500;
    color: #1a2e4a;
    font-family: var(--font, system-ui, sans-serif);
    line-height: 1.35;
  }

  &__contrib-desc {
    margin: 0;
    font-size: 14px;
    color: #64748b;
    font-family: var(--font, system-ui, sans-serif);
    line-height: 1.55;
  }

  &__contrib-dl {
    display: flex;
    flex-direction: column;
    align-items: center;
    gap: 2px;
    flex-shrink: 0;
    min-width: 64px;
    padding: 8px 12px;
    background: #f8fafc;
    border: 1px solid #e8eef5;
    border-radius: 8px;
  }

  &__contrib-dl-num {
    font-size: 20px;
    font-weight: 500;
    color: #002569;
    font-family: var(--font, system-ui, sans-serif);
    line-height: 1;
  }

  &__contrib-dl-label {
    font-size: 10px;
    color: #94a3b8;
    font-family: var(--font, system-ui, sans-serif);
    text-transform: uppercase;
    letter-spacing: 0.04em;
  }

  &__contrib-footer {
    display: flex;
    align-items: center;
    justify-content: space-between;
    padding-top: 10px;
    border-top: 1px solid #f1f5f9;
  }

  &__contrib-meta {
    font-size: 12px;
    color: #94a3b8;
    font-family: var(--font, system-ui, sans-serif);
  }

  &__contrib-actions {
    display: flex;
    gap: 6px;
  }

  &__contrib-action-btn {
    display: inline-flex;
    align-items: center;
    gap: 5px;
    padding: 5px 10px;
    border: 1px solid #e2e8f0;
    border-radius: var(--radius-ctrl);
    background: none;
    font-size: 12px;
    font-weight: 500;
    color: #475569;
    font-family: var(--font, system-ui, sans-serif);
    cursor: pointer;
    transition: background 0.12s, border-color 0.12s, color 0.12s;

    &:hover { background: #f8fafc; border-color: #007DB7; color: #007DB7; }
  }

  // ── Empty state ───────────────────────────────────────────────────────────
  &__empty {
    display: flex;
    flex-direction: column;
    align-items: center;
    justify-content: center;
    gap: 10px;
    padding: 80px 32px;
    text-align: center;
  }

  &__empty-label {
    margin: 8px 0 0;
    font-size: 16px;
    font-weight: 500;
    color: #424242;
    font-family: var(--font, system-ui, sans-serif);
  }

  &__empty-sub {
    margin: 0;
    font-size: 14px;
    color: #9e9e9e;
    font-family: var(--font, system-ui, sans-serif);
  }
}

// ── PrimeNG component overrides ─────────────────────────────────────────────

::ng-deep {
  // p-tabs: fill the remaining height of .ws
  p-tabs.p-component {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-height: 0;
    margin-top: 20px;
  }

  // p-tablist: the tab header bar
  // Reset PrimeNG's injected "border-style: solid" (which shows as thick border when no theme)
  p-tablist.p-tablist {
    flex-shrink: 0;
    overflow: visible;  // override PrimeNG's overflow: hidden
    border: none;       // reset injected border-style: solid
    background: transparent;
    padding: 0;

    .p-tablist-content {
      display: flex;
      align-items: flex-end;
      padding: 0 32px;
      border-bottom: 1px solid #ebebeb;
      overflow: visible;
      min-height: 0;
    }

    // Hide the animated slide bar — we use CSS border-bottom on each tab
    .p-tablist-active-bar { display: none; }

    // Hide scroll nav buttons (not using scrollable mode)
    .p-tablist-prev-button,
    .p-tablist-next-button { display: none; }
  }

  // p-tab: individual tab button
  // Reset PrimeNG's injected "border-style: solid" that shows thick borders without a theme
  p-tab.p-tab {
    border: none;    // reset injected border-style: solid
    background: transparent;
    margin: 0;
    padding: 10px 24px;
    font-size: 14px;
    font-family: var(--font, system-ui, sans-serif);
    color: #9e9e9e;
    cursor: pointer;
    border-bottom: 2px solid transparent;
    margin-bottom: -1px;
    outline: none;
    user-select: none;
    transition: color 0.15s, border-color 0.15s;

    &.p-tab-active {
      color: #007DB7;
      font-weight: 500;
      border-bottom-color: #007DB7;
    }

    &:not(.p-tab-active):hover { color: #424242; }
  }

  // p-tabpanels: fills remaining space below the tab bar
  // Reset injected padding
  p-tabpanels.p-tabpanels {
    flex: 1;
    display: flex;
    flex-direction: column;
    min-height: 0;
    overflow: hidden;
    background: transparent;
    padding: 0;
    outline: none;
  }

  // p-tabpanel (active): flex column so inner .ws__content can scroll
  p-tabpanel.p-tabpanel-active {
    display: flex;
    flex-direction: column;
    flex: 1;
    min-height: 0;
    outline: none;
    padding: 0;
  }

}

.ws__pills {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 16px 32px 0;
  flex-shrink: 0;
}

.ws__pills-spacer { flex: 1; }

.ws__pill {
  height: 32px;
  padding: 0 16px;
  border-radius: 20px;
  border: 1.5px solid #e0e0e0;
  background: transparent;
  font-size: 14px;
  font-family: var(--font, system-ui, sans-serif);
  color: #616161;
  cursor: pointer;
  outline: none;
  transition: background 0.13s, border-color 0.13s, color 0.13s;

  &--active {
    background: #007DB7;
    border-color: #007DB7;
    color: #fff;
    font-weight: 500;
  }

  &:not(&--active):hover {
    background: #f5f5f5;
    border-color: #bdbdbd;
  }
}

/* ── Recent grid cards ─────────────────────────────────────────────── */

.ws__recent-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 14px;

  @media (max-width: 1100px) { grid-template-columns: repeat(2, 1fr); }
}

.ws__rc {
  background: #fff;
  border: 1px solid #ebebeb;
  border-radius: 14px;
  padding: 22px;
  cursor: pointer;
  display: flex;
  flex-direction: column;
  box-shadow: 0 1px 2px rgba(12, 35, 60, 0.04), 0 2px 6px rgba(12, 35, 60, 0.05);
  transition: transform 0.22s ease, box-shadow 0.22s ease, border-color 0.22s ease;

  &:hover {
    transform: translateY(-3px);
    box-shadow: 0 8px 24px rgba(12, 35, 60, 0.10), 0 2px 6px rgba(12, 35, 60, 0.05);
    border-color: rgba(0, 125, 183, 0.20);
  }
}

.ws__rc-tag-row {
  display: flex;
  align-items: center;
  margin-bottom: 10px;
}

.ws__rc-tag {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.03em;
  padding: 3px 8px;
  border-radius: 4px;
  font-family: var(--font, system-ui, sans-serif);

  &--blue   { background: rgba(0, 125, 183, 0.10);  color: #005a8a; }
  &--violet { background: rgba(109, 40, 217, 0.10); color: #5b21b6; }
  &--amber  { background: rgba(180, 83, 9, 0.10);   color: #92400e; }
  &--teal   { background: rgba(6, 78, 59, 0.10);    color: #065f46; }
  &--rose   { background: rgba(71, 85, 105, 0.10);  color: #475569; }
}

.ws__rc-title {
  margin: 0 0 auto;
  padding-bottom: 20px;
  font-size: 15px;
  font-weight: 500;
  color: #212121;
  font-family: var(--font, system-ui, sans-serif);
  line-height: 1.4;
}

.ws__rc-footer {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding-top: 16px;
  border-top: 1px solid #f0f0f0;
  gap: 8px;
}

.ws__rc-time {
  display: inline-flex;
  align-items: center;
  gap: 5px;
  font-size: 11.5px;
  color: #9e9e9e;
  font-family: var(--font, system-ui, sans-serif);
}

.ws__rc-btn {
  width: 28px;
  height: 28px;
  border: none;
  background: none;
  cursor: pointer;
  border-radius: var(--radius-ctrl);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #007DB7;
  transition: background 0.15s;

  &:hover { background: rgba(0, 125, 183, 0.10); }
}

/* ── Contribution stats banner ────────────────────────────────────────────── */

.ws__contrib-stats {
  display: flex;
  align-items: center;
  gap: 0;
  background: linear-gradient(135deg, #f0f7ff 0%, #f5f0ff 100%);
  border: 1px solid #e0eaf5;
  border-radius: 12px;
  padding: 18px 24px;
  margin-bottom: 24px;
}

.ws__contrib-stats-left {
  display: flex;
  align-items: center;
  gap: 16px;
  flex-shrink: 0;
}

.ws__contrib-stats-right {
  display: flex;
  align-items: center;
  gap: 16px;
  margin-left: auto;
}

.ws__contrib-stat {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 2px;
  min-width: 80px;
}

.ws__contrib-stat-value {
  font-size: 22px;
  font-weight: 500;
  color: #002569;
  font-family: var(--font);
  line-height: 1.1;
}

.ws__contrib-stat-label {
  font-size: 12px;
  color: #64748b;
  font-family: var(--font);
}

.ws__contrib-stat-divider {
  width: 1px;
  height: 36px;
  background: #d1dde8;
  flex-shrink: 0;
}

.ws__contrib-stat-nudge {
  font-size: 12px;
  color: #475569;
  font-family: var(--font);
  margin: 0;
}


/* ── My Assets card grid ────────────────────────────────────────────────── */

.ws__asset-grid {
  display: grid;
  grid-template-columns: repeat(3, 1fr);
  gap: 16px;

  @media (max-width: 1200px) { grid-template-columns: repeat(2, 1fr); }
  @media (max-width: 700px)  { grid-template-columns: 1fr; }
}

.ws__asset-card {
  background: #fff;
  border: 1px solid #ebebeb;
  border-radius: 14px;
  padding: 18px 20px;
  display: flex;
  flex-direction: column;
  box-shadow: 0 1px 2px rgba(12, 35, 60, 0.04), 0 2px 6px rgba(12, 35, 60, 0.05);
  transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;

  &:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 24px rgba(12, 35, 60, 0.10);
    border-color: rgba(0, 125, 183, 0.20);
  }
}

.ws__asset-card-top {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 12px;
}

.ws__asset-menu-btn {
  width: 28px;
  height: 28px;
  border: none;
  background: none;
  cursor: pointer;
  border-radius: var(--radius-ctrl);
  display: flex;
  align-items: center;
  justify-content: center;
  color: #bdbdbd;
  transition: background 0.15s, color 0.15s;

  &:hover { background: #f5f5f5; color: #616161; }
}

.ws__asset-title {
  margin: 0 0 6px;
  font-size: 15px;
  font-weight: 500;
  color: #1a2e4a;
  line-height: 1.4;
  font-family: var(--font, system-ui, sans-serif);
}

.ws__asset-subtitle {
  margin: 0 0 16px;
  font-size: 12.5px;
  color: #64748b;
  line-height: 1.55;
  font-family: var(--font, system-ui, sans-serif);
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

/* Stepper */

.ws__asset-stepper {
  display: flex;
  align-items: flex-start;
  margin-bottom: 18px;
}

.ws__asset-step {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: 6px;
  flex-shrink: 0;

  &--done {
    .ws__asset-step-node {
      border: 2px dashed #007DB7;
      background: rgba(0, 125, 183, 0.07);
      color: #007DB7;
    }
    .ws__asset-step-label { color: #007DB7; }
  }

  &--active {
    .ws__asset-step-node {
      border: 2px solid #0a4d8c;
      background: #0a4d8c;
      color: #fff;
    }
    .ws__asset-step-label { color: #0a4d8c; font-weight: 500; }
  }

  &--complete {
    .ws__asset-step-node {
      border: 2px solid #10b981;
      background: #10b981;
      color: #fff;
    }
    .ws__asset-step-label { color: #10b981; font-weight: 500; }
  }

  &--pending {
    .ws__asset-step-node {
      border: 2px dashed #d4d4d4;
      color: transparent;
    }
    .ws__asset-step-label { color: #c8c8c8; }
  }
}

.ws__asset-step-node {
  width: 32px;
  height: 32px;
  border-radius: 50%;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: border-color 0.15s, background 0.15s;
}

.ws__asset-step-label {
  font-size: 10.5px;
  font-weight: 400;
  color: #9e9e9e;
  text-align: center;
  white-space: nowrap;
  font-family: var(--font, system-ui, sans-serif);
}

.ws__asset-connector {
  flex: 1;
  height: 0;
  border-top: 1.5px dashed #d4d4d4;
  margin-top: 15px;

  &--done     { border-top-color: #007DB7; }
  &--complete { border-top-color: #10b981; }
}

/* History tab — catalogue asset card wrapper */
.ws__history-asset {
  background: #fff;
  border: 1px solid #ebebeb;
  border-radius: 14px;
  padding: 14px;
  display: flex;
  flex-direction: column;
  min-height: 200px;
  box-shadow: 0 1px 2px rgba(12, 35, 60, 0.04), 0 2px 6px rgba(12, 35, 60, 0.05);
  transition: transform 0.2s ease, box-shadow 0.2s ease;

  &:hover {
    transform: translateY(-2px);
    box-shadow: 0 8px 24px rgba(12, 35, 60, 0.10);
  }

  .ws__rc-tag-row { margin-bottom: 10px; }

  .ws__card-desc { margin-bottom: 0; }
}

/* Fields */

.ws__asset-fields {
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 10px 12px;
  margin-bottom: 16px;
}

.ws__asset-field {
  display: flex;
  flex-direction: column;
  align-items: flex-start;
  gap: 4px;

  &--full { grid-column: 1 / -1; }
}

.ws__asset-field-label {
  font-size: 11.5px;
  color: #9e9e9e;
  font-family: var(--font, system-ui, sans-serif);
}

.ws__asset-field-value {
  font-size: 14px;
  color: #212121;
  font-family: var(--font, system-ui, sans-serif);
}

/* Footer */

.ws__asset-card-footer {
  margin-top: auto;
  padding-top: 14px;
  border-top: 1px solid #f0f0f0;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.ws__asset-view-link {
  font-size: 12.5px;
  font-weight: 500;
  color: #007DB7;
  text-decoration: none;
  font-family: var(--font, system-ui, sans-serif);

  &:hover { text-decoration: underline; }
}

.ws__asset-goto-link {
  display: inline-flex;
  align-items: center;
  gap: 4px;
  font-size: 12.5px;
  font-weight: 500;
  text-decoration: none;
  font-family: var(--font, system-ui, sans-serif);

  &--published {
    color: #007DB7;
    cursor: pointer;
    &:hover { text-decoration: underline; }
  }

  &--disabled {
    color: #c5d4de;
    cursor: default;
    pointer-events: none;
  }
}

