  color: var(--th-muted);
  line-height: 1.7;
  font-weight: 300;
  margin-bottom: 16px;
}

.pub-modal-actions {
  display: flex;
  gap: 10px;
  margin-bottom: 20px;
}

.pub-modal-link {
  font-size: 14px;
  color: var(--adb-blue);
  display: inline-flex;
  align-items: center;
  transition: opacity 0.12s;

  &:hover { opacity: 0.8; }
}

/* ── Chat ────────────────────────────────────────────────────────────────── */
.pub-modal-chat {
  flex: 1;
  display: flex;
  flex-direction: column;
  border: 1px solid var(--th-border);
  border-radius: 10px;
  overflow: hidden;
  min-height: 0;
}

.pub-modal-chat-history {
  flex: 1;
  overflow-y: auto;
  padding: 12px;
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-height: 80px;
  max-height: 200px;
}

.pub-modal-chat-hint {
  font-size: 12px;
  color: var(--th-muted);
  text-align: center;
  padding: 16px 0;
}

.pub-modal-msg {
  max-width: 90%;
  font-size: 14px;
  color: var(--th-text);
  line-height: 1.6;

  &--user {
    margin-left: auto;

    .pub-modal-msg-text {
      background: var(--adb-blue);
      color: #fff;
      padding: 8px 12px;
      border-radius: 14px 14px 4px 14px;
    }
  }
}

.pub-modal-msg-text {
  line-height: 1.6;
}

.pub-modal-msg-dots {
  display: flex;
  gap: 5px;
  padding: 6px 0;

  span {
    width: 5px;
    height: 5px;
    border-radius: 50%;
    background: var(--adb-blue);
    animation: pulse 1.2s ease-in-out infinite;
    display: inline-block;
  }
}

.pub-modal-chat-form {
  display: flex;
  align-items: center;
  gap: 8px;
  padding: 8px 12px;
  border-top: 1px solid var(--th-border);
  flex-shrink: 0;
}

.pub-modal-chat-input {
  flex: 1;
  background: none;
  border: none;
  outline: none;
  font-size: 14px;
  color: var(--th-text);
  font-family: var(--font);

  &::placeholder { color: var(--th-muted); }

  &:disabled { opacity: 0.6; }
}

.pub-modal-chat-send {
  width: 30px;
  height: 30px;
  border-radius: 50%;
  background: var(--adb-blue);
  border: none;
  cursor: pointer;
  color: #fff;
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  transition: opacity 0.15s;

  &:disabled {
    opacity: 0.4;
    cursor: default;
  }
}

