import {
  Component, ChangeDetectionStrategy, AfterViewInit, OnDestroy,
  ElementRef, inject, signal,
} from '@angular/core';
import { CommonModule } from '@angular/common';
import { Router } from '@angular/router';
import { AuroraLightComponent } from '../../shared/ui/aurora-light/aurora-light.component';
import { PromptBarComponent } from '../../shared/ui/prompt-bar/prompt-bar.component';
import gsap from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

gsap.registerPlugin(ScrollTrigger);

// ── Gradient shader ──────────────────────────────────────────────────────────
// A single fullscreen-triangle WebGL canvas spans from the hero's gradient
// start through the unlocks section's fade-out point (positioned/sized by
// initGradientCanvas). Rendering both zones from one shader — instead of two
// independently-tuned CSS gradients on separate elements — guarantees the
// color field is pixel-continuous across the section boundary; two hand-tuned
// CSS layers kept drifting out of sync at the seam.

const GRADIENT_VERT = `
attribute vec2 aPosition;
varying vec2 vUv;
void main() {
  vUv = aPosition * 0.5 + 0.5;
  gl_Position = vec4(aPosition, 0.0, 1.0);
}
`;

const GRADIENT_FRAG = `
precision mediump float;
varying vec2 vUv;
uniform float uTime;
uniform vec4 uAlphaStops; // fadeInStart, fadeInEnd, fadeOutStart, fadeOutEnd (local uv.y, 0=top)

float hash(vec2 p) {
  p = fract(p * vec2(123.34, 456.21));
  p += dot(p, p + 45.32);
  return fract(p.x * p.y);
}

float noise(vec2 p) {
  vec2 i = floor(p);
  vec2 f = fract(p);
  float a = hash(i);
  float b = hash(i + vec2(1.0, 0.0));
  float c = hash(i + vec2(0.0, 1.0));
  float d = hash(i + vec2(1.0, 1.0));
  vec2 u = f * f * (3.0 - 2.0 * f);
  return mix(a, b, u.x) + (c - a) * u.y * (1.0 - u.x) + (d - b) * u.x * u.y;
}

float fbm(vec2 p) {
  float v = 0.0;
  float amp = 0.5;
  for (int i = 0; i < 4; i++) {
    v += amp * noise(p);
    p *= 2.0;
    amp *= 0.5;
  }
  return v;
}

void main() {
  vec2 uv = vUv;

  // Organic flow field — two octave-shifted fbm samples drifting at
  // different rates so the blend line never looks like a static gradient.
  vec2 flowP = vec2(uv.x * 2.4, uv.y * 3.2) + vec2(uTime * 0.055, -uTime * 0.032);
  float n  = fbm(flowP);
  float n2 = fbm(flowP * 1.8 + 7.3 - uTime * 0.028);

  float diag = uv.x * 0.7 + uv.y * 0.3;
  diag += (n - 0.5) * 0.4 + (n2 - 0.5) * 0.18;
  diag = clamp(diag, 0.0, 1.0);

  vec3 blue  = vec3(0.0, 0.4902, 0.7176);  // #007DB7
  vec3 teal  = vec3(0.2275, 0.6118, 0.5804);
  vec3 green = vec3(0.5529, 0.7765, 0.2471); // #8DC63F

  vec3 color = mix(blue, teal, smoothstep(0.0, 0.55, diag));
  color = mix(color, green, smoothstep(0.45, 1.0, diag));

  float alphaIn  = smoothstep(uAlphaStops.x, uAlphaStops.y, uv.y);
  float alphaOut = 1.0 - smoothstep(uAlphaStops.z, uAlphaStops.w, uv.y);
  float intensity = clamp(alphaIn * alphaOut, 0.0, 1.0);

  // Breathing shimmer, phase-shifted by position so it ripples rather
  // than pulsing uniformly.
  intensity *= 0.78 + 0.22 * sin(uTime * 0.28 + uv.y * 4.0 + uv.x * 2.0);
  intensity *= 0.52;

  // Blend against white in the shader and output fully opaque — avoids the
  // double-darkening caused by premultiplied-alpha mismatch on canvas compositing.
  gl_FragColor = vec4(mix(vec3(1.0), color, intensity), 1.0);
}
`;

function compileShader(gl: WebGLRenderingContext, type: number, source: string): WebGLShader | null {
  const shader = gl.createShader(type);
  if (!shader) return null;
  gl.shaderSource(shader, source);
  gl.compileShader(shader);
  if (!gl.getShaderParameter(shader, gl.COMPILE_STATUS)) {
    gl.deleteShader(shader);
    return null;
  }
  return shader;
}

type UnlocksTab = 'discover' | 'connect' | 'reuse' | 'trust';

interface RoadmapItem {
  quarter: string;
  title: string;
  desc: string;
}

@Component({
  selector: 'app-whats-new',
  standalone: true,
  imports: [CommonModule, AuroraLightComponent, PromptBarComponent],
  templateUrl: './whats-new.component.html',
  styleUrl: './whats-new.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class WhatsNewComponent implements AfterViewInit, OnDestroy {
  readonly router = inject(Router);
  readonly el     = inject(ElementRef<HTMLElement>);

  onWnSearch(q: string) {
    this.router.navigate(['/search'], q ? { queryParams: { q } } : {});
  }

  activeTab = signal<UnlocksTab>('discover');

  readonly tabs: { id: UnlocksTab; label: string }[] = [
    { id: 'discover', label: 'Discover' },
    { id: 'connect',  label: 'Connect' },
    { id: 'reuse',    label: 'Reuse' },
    { id: 'trust',    label: 'Trust' },
  ];

  readonly tabContent: Record<UnlocksTab, { title: string; body: string[] }> = {
    discover: {
      title: 'Discover Existing Capabilities',
      body: [
        'Every project, every evaluation, and every development result contributes to ADB\'s collective intelligence. Why start from scratch when you can build on what ADB already knows?',
        'DataNex 2.0 is designed around ADB\'s work. Describe the development challenge or outcome you want to achieve and it can connect you to relevant and trusted knowledge, assets, and capabilities that already exist across ADB.',
        'By surfacing relevant insights and reusable assets from across the bank, DataNex 2.0 helps strengthen decisions, improve operational efficiency, and strengthen development impact.',
      ],
    },
    connect: {
      title: 'Connect Across the Bank',
      body: [
        'Break down silos between departments, divisions, and resident missions. DataNex surfaces the right people, expertise, and institutional knowledge — exactly when you need it.',
        'Explore who across ADB has worked on similar themes, sectors, or geographies. Build on their work rather than duplicating effort across the institution.',
      ],
    },
    reuse: {
      title: 'Reuse What Works',
      body: [
        'Access integration capabilities such as APIs, dashboards, and analytical tools that other teams have already built and validated.',
        'Reduce duplicated effort. Increase institutional leverage. Every asset contributed becomes a shared building block for the next project.',
      ],
    },
    trust: {
      title: 'Trust What You Find',
      body: [
        'Every asset on DataNex carries provenance metadata — who created it, when it was last updated, and how it has been used across the institution.',
        'Trust status indicators, quality certifications, and peer reviews mean you always know the reliability of what you\'re working with.',
      ],
    },
  };

  readonly roadmapItems: RoadmapItem[] = [
    { quarter: 'Q4 2026', title: 'Additional Assets',    desc: 'Over 1,000 more assets coming your way!' },
    { quarter: 'Q1 2027', title: 'Interact with Assets', desc: "Explore and interact with the assets before 'check-out'." },
    { quarter: 'Q2 2027', title: 'One-Stop Experience',  desc: 'Everything and more that you loved about ADB Genie in one space!' },
    { quarter: 'Q3 2027', title: 'Reuse Capabilities',   desc: 'Access integration capabilities such as APIs.' },
    { quarter: 'Q4 2027', title: 'Contribute Assets',    desc: 'Help ADB scale its impact by contributing assets.' },
  ];

  ngAfterViewInit(): void {
    const host = this.el.nativeElement;

    ScrollTrigger.defaults({ scroller: host });

    // Hero entrance — staggered lines
    gsap.from(['.wn__hero-badge', '.wn__hero-h1', '.wn__hero-sub', '.wn__hero-cta', '.wn__hero-frame'], {
      y: 36, opacity: 0, duration: 0.9, stagger: 0.11, ease: 'power3.out', delay: 0.15,
    });

    // Generic section reveals
    gsap.utils.toArray<HTMLElement>('.wn__reveal').forEach(el => {
      gsap.from(el, {
        scrollTrigger: { trigger: el, start: 'top 88%', toggleActions: 'play none none none' },
        y: 22, opacity: 0, duration: 0.65, ease: 'power2.out',
      });
    });

    this.initGradientCanvas();
  }

  ngOnDestroy(): void {
    ScrollTrigger.getAll().forEach(t => t.kill());
    if (this.gradientRaf !== undefined) cancelAnimationFrame(this.gradientRaf);
    this.gradientCleanupFns.forEach(fn => fn());
  }

  setTab(id: UnlocksTab): void {
    this.activeTab.set(id);
  }

  signIn(): void {
    this.router.navigate(['/']);
  }

  private gradientRaf?: number;
  private readonly gradientCleanupFns: Array<() => void> = [];

  private initGradientCanvas(): void {
    const host = this.el.nativeElement;
    const canvas    = host.querySelector('.wn__gradient') as HTMLCanvasElement | null;
    const wnEl      = host.querySelector('.wn') as HTMLElement | null;
    const heroEl    = host.querySelector('.wn__hero') as HTMLElement | null;
    const unlocksEl = host.querySelector('.wn__unlocks') as HTMLElement | null;
    if (!canvas || !wnEl || !heroEl || !unlocksEl) return;

    const gl = canvas.getContext('webgl', { alpha: false });
    if (!gl) return; // no WebGL support — page still reads fine on plain white

    const vert = compileShader(gl, gl.VERTEX_SHADER, GRADIENT_VERT);
    const frag = compileShader(gl, gl.FRAGMENT_SHADER, GRADIENT_FRAG);
    const program = gl.createProgram();
    if (!vert || !frag || !program) return;

    gl.attachShader(program, vert);
    gl.attachShader(program, frag);
    gl.linkProgram(program);
    if (!gl.getProgramParameter(program, gl.LINK_STATUS)) return;
    gl.useProgram(program);

    const posBuffer = gl.createBuffer();
    gl.bindBuffer(gl.ARRAY_BUFFER, posBuffer);
    // One oversized triangle covering clip space — cheaper than a quad, no index buffer needed.
    gl.bufferData(gl.ARRAY_BUFFER, new Float32Array([-1, -1, 3, -1, -1, 3]), gl.STATIC_DRAW);
    const aPosition = gl.getAttribLocation(program, 'aPosition');
    gl.enableVertexAttribArray(aPosition);
    gl.vertexAttribPointer(aPosition, 2, gl.FLOAT, false, 0, 0);

    const uTime       = gl.getUniformLocation(program, 'uTime');
    const uAlphaStops = gl.getUniformLocation(program, 'uAlphaStops');

    const dpr = Math.min(window.devicePixelRatio || 1, 2);

    const reposition = (): void => {
      const wnRect      = wnEl.getBoundingClientRect();
      const heroRect    = heroEl.getBoundingClientRect();
      const unlocksRect = unlocksEl.getBoundingClientRect();

      const bandHeight = window.innerWidth <= 960 ? 380 : 620;
      const topPx     = (heroRect.bottom - wnRect.top) - bandHeight;
      const fadeEndPx = (unlocksRect.top - wnRect.top) + unlocksRect.height * 0.62;
      const heightPx  = Math.max(fadeEndPx - topPx, 1);

      canvas.style.top    = `${topPx}px`;
      canvas.style.height = `${heightPx}px`;
      canvas.width  = Math.round(wnRect.width * dpr);
      canvas.height = Math.round(heightPx * dpr);
      gl.viewport(0, 0, canvas.width, canvas.height);

      const fadeInEnd    = Math.min((bandHeight * 0.55) / heightPx, 1);
      const fadeOutSpan  = (unlocksRect.height * 0.62) / heightPx;
      const fadeOutStart = Math.max(1 - fadeOutSpan, fadeInEnd);
      gl.uniform4f(uAlphaStops, 0, fadeInEnd, fadeOutStart, 1);
    };

    reposition();
    const ro = new ResizeObserver(() => reposition());
    ro.observe(wnEl);
    this.gradientCleanupFns.push(() => ro.disconnect());

    const reduceMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
    const start = performance.now();

    const draw = (t: number): void => {
      gl.uniform1f(uTime, reduceMotion ? 0 : (t - start) / 1000);
      gl.clearColor(1, 1, 1, 1);
      gl.clear(gl.COLOR_BUFFER_BIT);
      gl.drawArrays(gl.TRIANGLES, 0, 3);
      if (!reduceMotion) this.gradientRaf = requestAnimationFrame(draw);
    };
    draw(start);
  }
}

styleUrlsData.data:
:host {
  display: block;
  overflow-y: auto;
  height: 100%;
  font-family: var(--font, system-ui, sans-serif);

  --wn-bg: #FAF7F2;
  --wn-ink: #221F1B;
  --wn-ink-muted: #6B6660;
  --wn-blue: var(--adb-blue);
  --wn-green: var(--adb-green);
  --wn-border: #E8E2D8;
  background: var(--wn-bg);
}

.wn {
  position: relative;
  background: #fff;
}

// Single WebGL canvas positioned/sized via TS to span from the hero's
// gradient start through the unlocks fade-out point — see initGradientCanvas
// in the component. .wn__hero/.wn__unlocks are transparent so it shows
// through both without a seam between two separately-tuned CSS layers.
.wn__gradient {
  position: absolute;
  left: 0;
  width: 100%;
  z-index: 0;
  pointer-events: none;
  display: block;
}

// ── Hero ─────────────────────────────────────────────────────────────────────
.wn__hero {
  position: relative;
  z-index: 1;
  overflow: hidden;
  background: linear-gradient(135deg, #d8f2fb 0%, #e9f8c8 100%);
}

.wn__aurora {
  position: absolute;
  inset: 0;
  z-index: 0;
  pointer-events: none;
  overflow: hidden;
}

.wn__aurora-fade {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  height: 42%;
  z-index: 1;
  pointer-events: none;
  background: linear-gradient(to bottom, transparent 0%, #ffffff 80%);
}

.wn__grain {
  position: absolute;
  inset: 0;
  pointer-events: none;
  z-index: 1;
  opacity: 0.03;
  background-image: url("data:image/svg+xml,%3Csvg viewBox='0 0 256 256' xmlns='http://www.w3.org/2000/svg'%3E%3Cfilter id='n'%3E%3CfeTurbulence type='fractalNoise' baseFrequency='0.7' numOctaves='4' stitchTiles='stitch'/%3E%3C/filter%3E%3Crect width='100%25' height='100%25' filter='url(%23n)'/%3E%3C/svg%3E");
  background-repeat: repeat;
  background-size: 140px 140px;
}

.wn__hero-inner {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: center;
  gap: 64px;
  max-width: 1440px;
  margin: 0 auto;
  padding: 100px 72px 60px;
}

.wn__hero-content {
  flex: 0 1 460px;
}

.wn__hero-visual {
  flex: 1 1 0%;
  min-width: 0;
  max-width: 720px;
}

.wn__hero-frame {
  border-radius: 12px;
  border: 1px solid var(--wn-border);
  background: #fff;
  box-shadow: 0 30px 60px -24px rgba(34, 31, 27, 0.2);
  overflow: hidden;
}

.wn__hero-frame-bar {
  display: flex;
  align-items: center;
  gap: 6px;
  padding: 10px 14px;
  background: #F3EEE5;
  border-bottom: 1px solid var(--wn-border);
}

.wn__hero-frame-dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: #D8D0C2;
}

.wn__hero-frame-img {
  display: block;
  width: 100%;
  height: auto;
}

.wn__hero-badge {
  display: inline-flex;
  align-items: center;
  font-size: 12px;
  font-weight: 500;
  letter-spacing: 0.06em;
  color: var(--wn-blue);
  border: 1px solid rgba(0, 125, 183, 0.28);
  background: rgba(0, 125, 183, 0.06);
  border-radius: 999px;
  padding: 4px 12px;
  margin-bottom: 28px;
}

.wn__hero-h1 {
  font-family: var(--font);
  font-size: clamp(42px, 5vw, 64px);
  font-weight: 500;
  color: var(--wn-ink);
  line-height: 1.08;
  letter-spacing: -0.01em;
  margin: 0 0 20px;
}

.wn__hero-accent {
  color: var(--wn-blue);
}

.wn__hero-sub {
  font-size: 15px;
  line-height: 1.65;
  color: var(--wn-ink-muted);
  margin: 0 0 36px;
  max-width: 460px;
}

.wn__hero-prompt {
  width: 100%;
  max-width: 480px;
}

// ── What This Unlocks ─────────────────────────────────────────────────────────
// Empty section that anchors the WebGL canvas fade-out calculation.
.wn__unlocks {
  position: relative;
  background: transparent;
  height: 80px;
}

// Lives inside .wn__hero, on top of .wn__gradient — see markup.
.wn__unlocks-head {
  position: relative;
  z-index: 2;
  display: flex;
  align-items: flex-start;
  gap: 80px;
  max-width: 1440px;
  margin: 0 auto;
  padding: 64px 72px 80px;
}

.wn__unlocks-h2 {
  font-family: var(--font);
  font-size: clamp(26px, 3vw, 38px);
  font-weight: 500;
  line-height: 1.2;
  letter-spacing: -0.01em;
  margin: 0;
  flex-shrink: 0;
  background: linear-gradient(135deg, #007DB7 0%, #3ab8a0 45%, #8DC63F 100%);
  -webkit-background-clip: text;
  -webkit-text-fill-color: transparent;
  background-clip: text;
}

.wn__unlocks-right {
  display: flex;
  flex-direction: column;
  gap: 20px;
  flex: 1;
  min-width: 0;
}

.wn__tabs {
  display: flex;
  flex-wrap: wrap;
  gap: 8px;
}

.wn__tab {
  padding: 7px 16px;
  border: 1px solid var(--wn-border);
  background: rgba(255, 255, 255, 0.55);
  backdrop-filter: blur(6px);
  border-radius: 999px;
  font-size: 14px;
  font-weight: 500;
  font-family: inherit;
  color: var(--wn-ink-muted);
  cursor: pointer;
  text-align: left;
  transition: color 0.15s, background 0.15s, border-color 0.15s;
  white-space: nowrap;

  &:hover { color: var(--wn-ink); border-color: #d8d0c2; }

  &--active {
    color: #fff;
    background: var(--wn-blue);
    border-color: var(--wn-blue);
  }
}

.wn__tab-body {
  max-width: 100%;
}

.wn__tab-title {
  font-family: var(--font);
  font-size: 20px;
  font-weight: 500;
  color: var(--wn-ink);
  margin: 0 0 18px;
  letter-spacing: -0.005em;
}

.wn__tab-para {
  font-size: 14px;
  line-height: 1.72;
  color: var(--wn-ink-muted);
  margin: 0 0 14px;

  &:last-child { margin-bottom: 0; }
}

// ── What's Next ───────────────────────────────────────────────────────────────
.wn__next {
  background: #fff;
  border-top: 1px solid var(--wn-border);
  padding: 80px 0 64px;
}

.wn__next-head {
  margin-bottom: 40px;
  padding: 0 72px;
}

.wn__next-h2 {
  font-family: var(--font);
  font-size: clamp(26px, 3vw, 36px);
  font-weight: 500;
  color: var(--wn-ink);
  letter-spacing: -0.01em;
  margin: 0 0 8px;
}

.wn__next-sub {
  font-size: 14px;
  color: var(--wn-ink-muted);
  margin: 0;
}

// ── Horizontal scroll timeline ────────────────────────────────────────────────
.wn__timeline {
  overflow-x: auto;
  overflow-y: visible;
  scrollbar-width: none;
  &::-webkit-scrollbar { display: none; }
}

.wn__timeline-track {
  display: flex;
  align-items: flex-start;
  padding: 32px 72px 40px;
  min-width: max-content;
  position: relative;

  // Horizontal line running through the badge centres
  &::before {
    content: '';
    position: absolute;
    top: 50px; // aligns with centre of 36px badge + 32px top padding
    left: 72px;
    right: 72px;
    height: 1px;
    background: var(--wn-border);
  }
}

.wn__timeline-col {
  flex-shrink: 0;
  width: 280px;
  padding-right: 48px;
  position: relative;
}

.wn__timeline-badge {
  display: inline-flex;
  align-items: center;
  height: 36px;
  padding: 0 16px;
  background: var(--wn-ink);
  color: #fff;
  border-radius: 999px;
  font-size: 12px;
  font-weight: 500;
  font-family: var(--font);
  letter-spacing: 0.01em;
  position: relative;
  z-index: 1;
  margin-bottom: 20px;
}

.wn__timeline-text {
  font-size: 13.5px;
  line-height: 1.65;
  color: var(--wn-ink-muted);
  margin: 0;
  max-width: 230px;
}

.wn__timeline-item-title {
  font-weight: 500;
  color: var(--wn-ink);
  font-family: var(--font);
}

.wn__timeline-item-desc {
  font-weight: 400;
}

.wn__next-cta-row {
  display: flex;
  justify-content: center;
  padding-top: 48px;
}

.wn__next-cta {
  height: 42px;
  padding: 0 28px;
  background: var(--wn-blue);
  border: 1px solid var(--wn-blue);
  border-radius: 6px;
  font-size: 13.5px;
  font-weight: 500;
  font-family: inherit;
  color: #fff;
  cursor: pointer;
  transition: background 0.15s;

  &:hover { background: #006996; }
}

// ── Footer ────────────────────────────────────────────────────────────────────
.wn__footer {
  background: #fff;
  padding: 56px 72px 0;
  border-top: 1px solid var(--wn-border);
}

.wn__footer-inner {
  display: flex;
  gap: 80px;
  padding-bottom: 48px;
  border-bottom: 1px solid var(--wn-border);
}

.wn__footer-brand {
  flex: 1;
}

.wn__footer-logo {
  display: flex;
  align-items: center;
  gap: 10px;
  margin-bottom: 12px;
}

.wn__footer-logo-text {
  font-size: 14px;
  font-weight: 500;
  color: var(--wn-ink);
}

.wn__footer-ai {
  color: var(--wn-ink-muted);
  font-weight: 400;
}

.wn__footer-tagline {
  font-size: 12px;
  color: var(--wn-ink-muted);
  margin: 0;
  line-height: 1.6;
}

.wn__footer-col {
  display: flex;
  flex-direction: column;
  gap: 10px;
  min-width: 160px;
}

.wn__footer-col-title {
  font-size: 12px;
  font-weight: 500;
  color: var(--wn-ink-muted);
  margin: 0 0 2px;
}

.wn__footer-link {
  font-size: 14px;
  color: var(--wn-ink-muted);
  text-decoration: none;
  transition: color 0.12s;

  &:hover { color: var(--wn-ink); }
}

.wn__footer-copy {
  padding: 20px 0;
  font-size: 11.5px;
  color: var(--wn-ink-muted);
  opacity: 0.7;
}

// ── Responsive ────────────────────────────────────────────────────────────────
@media (max-width: 960px) {
  .wn__hero-inner { flex-direction: column; align-items: stretch; gap: 40px; padding: 64px 36px 40px; }
  .wn__hero-content { flex-basis: auto; }
  .wn__hero-visual { max-width: 100%; }
  .wn__hero-band { height: 520px; }
  .wn__unlocks-head { flex-direction: column; gap: 24px; padding: 40px 36px 60px; }
  .wn__unlocks-right { gap: 16px; }

  .wn__next { padding: 56px 0 48px; }
  .wn__next-head { padding: 0 36px; margin-bottom: 32px; }
  .wn__timeline-track { padding: 32px 36px 40px; &::before { left: 36px; right: 36px; } }
  .wn__next-cta-row { padding-top: 36px; }

  .wn__footer { padding: 48px 36px 0; }
  .wn__footer-inner { flex-direction: column; gap: 36px; }
}

